    lock.acquire()
    lock.release()
    return x

if __name__ == '__main__':
    lock = RLock()
    with Pool(2) as p:
        try:
            p.starmap(f, [(lock, 1)])
        except RuntimeError as e:
            print('RUNTIME_ERR')
        except Exception as e:
